mat2 MatriceRotation2D(float angle) {
    return mat2(cos(angle), sin(angle), -sin(angle), cos(angle));
}

void orienterVecteur(inout vec3 vecteur, vec2 anglesOrientation) {
    vecteur.yz *= MatriceRotation2D(anglesOrientation.y);
    vecteur.xz *= MatriceRotation2D(anglesOrientation.x);
}

void mainImage(out vec4 couleurFragment, vec2 coordFragment) {
    vec2 resolution = iResolution.xy;
    vec2 positionSouris = iMouse.z > 0.0 ? (iMouse.xy - resolution * 0.5) / resolution.y * 4.0 : vec2(iTime, sin(iTime * 0.6)) * 0.5;

    vec3 origineRayon = vec3(0.0, 0.0, -18.0);
    vec3 directionRayon = normalize(vec3(coordFragment + coordFragment - resolution, resolution.y * 2.9));

    orienterVecteur(directionRayon, positionSouris);
    orienterVecteur(origineRayon, positionSouris);

    couleurFragment = vec4(0.0);

    float distanceRayon = 0.4;
    float distanceSurface;
    float frequenceBruit;
    float angleSecteur;
    float amplitudeBruit;

    vec3 positionPoint;
    vec3 positionBruit;
    vec3 grillePoint;
    vec3 interpolationPoint;

    for(int i = 0; i < 91; i++) {
        frequenceBruit = 0.4;
        amplitudeBruit = 0.5;

        positionPoint = origineRayon + directionRayon * distanceRayon;
        positionBruit = positionPoint * 2.7 + iTime;

        for(int k = 0; k < 3; k++) {
            grillePoint = floor(positionBruit);
            interpolationPoint = fract(positionBruit);
            interpolationPoint = interpolationPoint * interpolationPoint * (3.0 - interpolationPoint - interpolationPoint);

            vec4 indicesBruit = dot(grillePoint, vec3(1.0, 57.0, 113.0)) + vec4(0.0, 57.0, 113.0, 170.0);
            vec4 valeursAlea = mix(fract(sin(indicesBruit) * 40000.0), fract(sin(indicesBruit + 1.0) * 40000.0), interpolationPoint.x);

            frequenceBruit += amplitudeBruit * mix(mix(valeursAlea.x, valeursAlea.y, interpolationPoint.y), mix(valeursAlea.z, valeursAlea.w, interpolationPoint.y), interpolationPoint.z);

            amplitudeBruit *= 0.5;
            positionBruit += positionBruit;
        }

        positionPoint += sin(positionPoint.zxy * 2.0 + iTime) * 0.2;

        angleSecteur = mod(atan(positionPoint.z, positionPoint.x) + 0.098, 0.196) - 0.098;
        positionPoint.xz = vec2(cos(angleSecteur), sin(angleSecteur)) * length(positionPoint.xz);

        positionPoint -= 4.0 * clamp(round(positionPoint * 0.25), -2.0, 2.0);

        distanceSurface = length(positionPoint) - 1.2 - frequenceBruit * 0.5;

        if (distanceSurface < 1.0) {
            couleurFragment += 0.01 / (distanceSurface * distanceSurface + 0.01) * vec4(1.0 - frequenceBruit * vec3(0.1, 0.8, 0.5), 1.0);
        }

        distanceRayon += max(distanceSurface, 0.04);
    }

    couleurFragment = pow(couleurFragment * 0.03, vec4(0.6));
}
